CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE users(id uuid PRIMARY KEY, login text UNIQUE NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('chief','operator','accountant','sysadmin','auditor')), password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, telegram_id bigint UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash bytea PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE merchants(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE tariffs(id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), rate_bp integer NOT NULL CHECK(rate_bp BETWEEN 0 AND 10000), valid_from date NOT NULL, active boolean NOT NULL DEFAULT true, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE banks(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE custodians(id uuid PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('collector','chief','operator')), active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX one_chief_custodian ON custodians(kind) WHERE kind='chief';
CREATE TABLE cards(id uuid PRIMARY KEY, bank_id uuid NOT NULL REFERENCES banks(id), owner_label text NOT NULL, mask text NOT NULL, last4 char(4) NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','blocked','retired')), UNIQUE(bank_id,mask));
CREATE TABLE card_assignments(user_id uuid NOT NULL REFERENCES users(id), card_id uuid NOT NULL REFERENCES cards(id), assigned_by uuid NOT NULL REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,card_id));
CREATE TABLE source_documents(id uuid PRIMARY KEY, kind text NOT NULL, filename text NOT NULL, sha256 text UNIQUE NOT NULL, media_type text NOT NULL, byte_size bigint NOT NULL, storage_path text NOT NULL, uploader_id uuid NOT NULL REFERENCES users(id), received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE registries(id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), source_id uuid NOT NULL UNIQUE REFERENCES source_documents(id), external_ref text NOT NULL, status text NOT NULL CHECK(status IN ('preview','posted','reversed')), total_cents bigint NOT NULL CHECK(total_cents>0), commission_cents bigint, rate_bp integer, manual_rate_bp integer, manual_reason text, manual_approved_by uuid REFERENCES users(id), manual_approved_at timestamptz, confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(merchant_id,external_ref));
CREATE TABLE registry_rows(id uuid PRIMARY KEY, registry_id uuid NOT NULL REFERENCES registries(id), row_no integer NOT NULL, sheet_name text NOT NULL DEFAULT '', raw jsonb NOT NULL, card_id uuid REFERENCES cards(id), amount_cents bigint, error_code text, external_order text, rrn text, bank_fee_cents bigint, bank_transfer_cents bigint, UNIQUE(registry_id,row_no));
CREATE TABLE tariff_adjustments(id uuid PRIMARY KEY, registry_id uuid NOT NULL REFERENCES registries(id), old_commission_cents bigint NOT NULL, new_commission_cents bigint NOT NULL, rate_bp integer NOT NULL, reason text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tariff_confirmations(preview_hash text PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), rate_bp integer NOT NULL, valid_from date NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), confirmed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE manual_rate_confirmations(preview_hash text PRIMARY KEY, registry_id uuid NOT NULL REFERENCES registries(id), rate_bp integer NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), confirmed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE observations(id uuid PRIMARY KEY, card_id uuid NOT NULL REFERENCES cards(id), observed_cents bigint NOT NULL, observed_at timestamptz NOT NULL, reporter_id uuid NOT NULL REFERENCES users(id), source text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drafts(id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','rejected','reversed')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), confirmed_by uuid REFERENCES users(id), confirmed_at timestamptz, confirmed_amount_cents bigint, version integer NOT NULL DEFAULT 1, idempotency_key text NOT NULL UNIQUE);
CREATE TABLE journal_entries(id uuid PRIMARY KEY, event_type text NOT NULL, event_id uuid NOT NULL, occurred_at timestamptz NOT NULL, recognition_at timestamptz NOT NULL, posted_at timestamptz NOT NULL DEFAULT now(), actor_id uuid NOT NULL REFERENCES users(id), currency char(3) NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), reversal_of uuid REFERENCES journal_entries(id), idempotency_key text NOT NULL UNIQUE, UNIQUE(event_type,event_id));
CREATE TABLE postings(id uuid PRIMARY KEY, entry_id uuid NOT NULL REFERENCES journal_entries(id), account text NOT NULL, side text NOT NULL CHECK(side IN ('debit','credit')), amount_cents bigint NOT NULL CHECK(amount_cents>0), merchant_id uuid REFERENCES merchants(id), card_id uuid REFERENCES cards(id), custodian_id uuid REFERENCES custodians(id), ref_id uuid, category text);
CREATE INDEX postings_account_dimension ON postings(account,merchant_id,card_id,custodian_id);
CREATE TABLE audit_events(id uuid PRIMARY KEY, at timestamptz NOT NULL DEFAULT now(), actor_id uuid REFERENCES users(id), actor_role text, channel text NOT NULL, action text NOT NULL, object_type text NOT NULL, object_id uuid, outcome text NOT NULL, reason text, detail jsonb NOT NULL DEFAULT '{}');
CREATE TABLE report_approvals(id uuid PRIMARY KEY, month date NOT NULL, snapshot jsonb NOT NULL, digest text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), approved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(month,digest));
CREATE TABLE telegram_updates(update_id bigint PRIMARY KEY, received_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable history'; END $$;
CREATE TRIGGER immutable_entries BEFORE UPDATE OR DELETE ON journal_entries FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_postings BEFORE UPDATE OR DELETE ON postings FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_tariff_adjustments BEFORE UPDATE OR DELETE ON tariff_adjustments FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_tariff_confirmations BEFORE UPDATE OR DELETE ON tariff_confirmations FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_manual_rate_confirmations BEFORE UPDATE OR DELETE ON manual_rate_confirmations FOR EACH ROW EXECUTE FUNCTION immutable_history();
